import pytest
from candidate import greatest_common_divisor


class TestGreatestCommonDivisor:
    def test_gcd_coprime_numbers(self):
        self.assertEqual(greatest_common_divisor(3, 5), 1)

    def test_gcd_common_factor_5(self):
        self.assertEqual(greatest_common_divisor(25, 15), 5)

    def test_gcd_common_factor_4(self):
        self.assertEqual(greatest_common_divisor(12, 8), 4)

    def test_gcd_common_factor_25(self):
        self.assertEqual(greatest_common_divisor(100, 75), 25)

    def test_gcd_one_divides_other(self):
        self.assertEqual(greatest_common_divisor(6, 3), 3)

    def test_gcd_reversed_order(self):
        self.assertEqual(greatest_common_divisor(15, 25), 5)

    def test_gcd_identical_numbers(self):
        self.assertEqual(greatest_common_divisor(7, 7), 7)

    def test_gcd_one_and_prime(self):
        self.assertEqual(greatest_common_divisor(1, 97), 1)

    def test_gcd_prime_and_composite(self):
        self.assertEqual(greatest_common_divisor(7, 49), 7)

    def test_gcd_second_is_zero(self):
        self.assertEqual(greatest_common_divisor(42, 0), 42)

    def test_gcd_first_is_zero(self):
        self.assertEqual(greatest_common_divisor(0, 42), 42)

    def test_gcd_both_zero(self):
        self.assertEqual(greatest_common_divisor(0, 0), 0)

    def test_gcd_with_one(self):
        self.assertEqual(greatest_common_divisor(1, 1), 1)

    def test_gcd_large_numbers(self):
        self.assertEqual(greatest_common_divisor(1073741824, 536870912), 536870912)

    def test_gcd_fibonacci_numbers(self):
        self.assertEqual(greatest_common_divisor(832040, 514229), 1)

    def test_gcd_large_coprime(self):
        self.assertEqual(greatest_common_divisor(1000000007, 999999999), 1)

    def test_gcd_multiple_of_large_number(self):
        self.assertEqual(greatest_common_divisor(999999999, 999999999), 999999999)

    def test_gcd_negative_first_argument(self):
        result = greatest_common_divisor(-12, 8)
        self.assertEqual(abs(result), 4)

    def test_gcd_negative_second_argument(self):
        result = greatest_common_divisor(12, -8)
        self.assertEqual(abs(result), 4)

    def test_gcd_both_negative(self):
        result = greatest_common_divisor(-25, -15)
        self.assertEqual(abs(result), 5)

    def test_gcd_negative_and_zero(self):
        result = greatest_common_divisor(-42, 0)
        self.assertEqual(abs(result), 42)

    def test_gcd_returns_int_type(self):
        result = greatest_common_divisor(25, 15)
        self.assertIsInstance(result, int)

    def test_gcd_none_first_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor(None, 5)

    def test_gcd_none_second_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor(5, None)

    def test_gcd_both_none_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor(None, None)

    def test_gcd_string_first_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor("hello", 5)

    def test_gcd_string_second_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor(5, "hello")

    def test_gcd_list_first_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor([3, 5], 5)

    def test_gcd_list_second_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            greatest_common_divisor(5, [3, 5])

    def test_gcd_boolean_input(self):
        self.assertEqual(greatest_common_divisor(True, 1), 1)

    def test_gcd_consecutive_integers(self):
        self.assertEqual(greatest_common_divisor(100, 101), 1)

    def test_gcd_perfect_square_and_number(self):
        self.assertEqual(greatest_common_divisor(16, 8), 8)

    def test_gcd_three_digit_numbers(self):
        self.assertEqual(greatest_common_divisor(245, 175), 35)

    def test_gcd_very_small_numbers(self):
        self.assertEqual(greatest_common_divisor(2, 3), 1)
        self.assertEqual(greatest_common_divisor(2, 4), 2)


if __name__ == '__main__':
    pytest.main([__file__, '-v'])
